import { createHash, createHmac, randomBytes, timingSafeEqual } from 'node:crypto';

// ── 1. SHA-256 general-purpose hashing ────────────────────────
const sha256 = (data) =>
  createHash('sha256').update(data).digest('hex');

// Avalanche effect: one character change → completely different digest
console.log(sha256('hello'));   // 2cf24dba5fb0a30e26e83b2ac5b9e29e1b161e5c1fa7425e73043362938b9824
console.log(sha256('Hello'));   // 185f8db32921bd46d35f35e2d58b8fbf1bee19e4d5a5f5bcbd3b6b04bdf16e3e
// ↑ Completely different despite a single-character difference

// Data integrity check: verify a file/payload has not been tampered with
function computeChecksum(data) {
  return sha256(data);
}
function verifyChecksum(data, expectedHash) {
  const actual = sha256(data);
  // Use timingSafeEqual even here as good habit
  const a = Buffer.from(actual, 'hex');
  const b = Buffer.from(expectedHash, 'hex');
  return a.length === b.length && timingSafeEqual(a, b);
}

const payload = JSON.stringify({ amount: 100, recipient: 'Bob' });
const checksum = computeChecksum(payload);
console.log('Checksum:', checksum);
console.log('Valid?', verifyChecksum(payload, checksum));  // true

// Simulate tampering
const tampered = JSON.stringify({ amount: 9999, recipient: 'Bob' });
console.log('Tampered?', verifyChecksum(tampered, checksum));  // false

// ── 2. HMAC: integrity + authenticity with a shared key ───────
const webhookSecret = randomBytes(32); // shared between sender and receiver

function signWebhook(payload, secret) {
  return createHmac('sha256', secret)
    .update(payload)
    .digest('hex');
}

function verifyWebhook(payload, signature, secret) {
  const expected = signWebhook(payload, secret);
  const a = Buffer.from(expected, 'hex');
  const b = Buffer.from(signature, 'hex');
  // CRITICAL: timingSafeEqual prevents timing side-channel attacks
  return a.length === b.length && timingSafeEqual(a, b);
}

const body = JSON.stringify({ event: 'payment.completed', amount: 100 });
const hmacSig = signWebhook(body, webhookSecret);
console.log('HMAC Signature:', hmacSig.slice(0, 20) + '...');
console.log('Valid webhook:', verifyWebhook(body, hmacSig, webhookSecret)); // true

// Attacker cannot forge HMAC without the secret key:
const forgedSig = createHmac('sha256', randomBytes(32)).update(body).digest('hex');
console.log('Forged valid?', verifyWebhook(body, forgedSig, webhookSecret)); // false

import { generateKeyPairSync, createSign, createVerify, randomBytes } from 'node:crypto';

// ── Ed25519 Digital Signatures ────────────────────────────────

// Key generation — in production, generate once and store securely
const { privateKey, publicKey } = generateKeyPairSync('ed25519', {
  privateKeyEncoding: { type: 'pkcs8', format: 'pem' },
  publicKeyEncoding: { type: 'spki', format: 'pem' },
});

function signDocument(message, privKey) {
  const signer = createSign('SHA512'); // Ed25519 uses SHA-512 internally
  signer.update(message, 'utf8');
  return signer.sign(privKey, 'hex');  // hex-encoded signature
}

function verifyDocument(message, signatureHex, pubKey) {
  const verifier = createVerify('SHA512');
  verifier.update(message, 'utf8');
  return verifier.verify(pubKey, signatureHex, 'hex');
}

const contract = 'I, Alice, agree to transfer $10,000 to Bob on 2026-01-01.';
const signature = signDocument(contract, privateKey);

console.log('Signature (first 40 chars):', signature.slice(0, 40) + '...');
console.log('Valid:', verifyDocument(contract, signature, publicKey)); // true

// Even a single character change invalidates the signature
const tampered = 'I, Alice, agree to transfer $1,000 to Bob on 2026-01-01.';
console.log('Tampered valid:', verifyDocument(tampered, signature, publicKey)); // false

// ── JWT-style payload signing (simplified) ────────────────────
function createToken(payload, privKey) {
  const header = Buffer.from(JSON.stringify({ alg: 'EdDSA', typ: 'JWT' })).toString('base64url');
  const body = Buffer.from(JSON.stringify(payload)).toString('base64url');
  const signingInput = `${header}.${body}`;
  const sig = signDocument(signingInput, privKey);
  const sigB64 = Buffer.from(sig, 'hex').toString('base64url');
  return `${signingInput}.${sigB64}`;
}

function verifyToken(token, pubKey) {
  const parts = token.split('.');
  if (parts.length !== 3) return null;
  const [header, body, sigB64] = parts;
  const sigHex = Buffer.from(sigB64, 'base64url').toString('hex');
  const valid = verifyDocument(`${header}.${body}`, sigHex, pubKey);
  if (!valid) return null;
  return JSON.parse(Buffer.from(body, 'base64url').toString('utf8'));
}

const token = createToken({ sub: 'alice', role: 'admin', exp: Date.now() + 3600000 }, privateKey);
console.log('Token:', token.slice(0, 60) + '...');
console.log('Decoded payload:', verifyToken(token, publicKey));

// ── Primitive selection guide ─────────────────────────────────
//
// SCENARIO                                    PRIMITIVE         ALGORITHM
// ─────────────────────────────────────────── ──────────────── ──────────────────────
// Verify file integrity (no adversary)        Hash             SHA-256
// Check data not tampered in transit          Hash             SHA-256
// Webhook signature (shared secret)           HMAC             HMAC-SHA256
// Session cookie signing (shared secret)      HMAC             HMAC-SHA256
// JWT with shared secret                      HMAC             HS256 (HMAC-SHA256)
// JWT with asymmetric key (public verify)     Digital Sig.     RS256 / ES256 / EdDSA
// Code signing (public distributes builds)    Digital Sig.     Ed25519 or RSA-PSS
// SSH host/user authentication               Digital Sig.     Ed25519
// TLS certificate signing                    Digital Sig.     ECDSA P-256 or RSA-PSS
// Store user password in DB                  Password Hash    Argon2id
// Derive encryption key from password        KDF              Argon2 or PBKDF2
// Commit hash / git object ID               Hash             SHA-256 (git migrating from SHA-1)
//
// ── Argon2id OWASP-recommended parameters (2023) ─────────────
const ARGON2_CONFIG = {
  type: 'argon2id',    // Hybrid: memory-hard + side-channel resistant
  memoryCost: 65536,   // 64 MiB — raise to 128 MiB if server allows
  timeCost: 3,         // 3 iterations over memory
  parallelism: 4,      // Use 4 CPU threads
  // Target: ~100-300ms per hash on production hardware
  // Effect: limits attacker to ~10 attempts/sec/core vs 10B/sec with SHA-256
};

// ── DO vs. DON'T for password storage ────────────────────────
const DONT = [
  "SHA-256('password123') — fast, no salt, GPU-crackable in seconds",
  "MD5(username + password) — predictable salt, broken algorithm",
  "AES-encrypt passwords — encryption is reversible, hash is not",
  "Plain SHA-256 even with salt — still ~10B hashes/sec on GPU",
  "Roll your own password hashing — always use battle-tested library",
];

const DO = [
  "argon2.hash(password, ARGON2_CONFIG) — auto-salted, slow, secure",
  "bcrypt.hash(password, 12) — cost factor 12 = 2^12 = 4096 rounds",
  "Tune cost so hashing takes 100-300ms on YOUR production hardware",
  "Re-hash on login when stored hash uses outdated parameters",
  "Never log, transmit, or display raw passwords at any stage",
];

// ── Timing attack example and prevention ─────────────────────
import { timingSafeEqual } from 'node:crypto';

// WRONG: reveals secret length and content via timing
function insecureCompare(a, b) {
  return a === b; // exits early on first mismatch — measurable timing difference
}

// CORRECT: always takes the same time regardless of where inputs differ
function secureCompare(a, b) {
  const bufA = Buffer.from(a);
  const bufB = Buffer.from(b);
  // Pad to same length first (timingSafeEqual requires equal length)
  if (bufA.length !== bufB.length) {
    timingSafeEqual(bufA, bufA); // still execute crypto op to avoid timing leak
    return false;
  }
  return timingSafeEqual(bufA, bufB);
}
